using System;using System.Linq;using System.Xml;using System.Collections.Generic;
namespace BeamScheduleFormatter {
/* Quantity = openings in EACH unit of the wall group (owner, 21 November 2026: Wall Qty 2 with one opening each = 2 openings).
   Total = a quantity saved before v6.0.35 that is the total for the whole group and could not be divided by the wall Qty. */
class OpeningLink {public string Wall,Schedule;public int Quantity;public bool Total;}
static class OpeningLinks {
 public static List<OpeningItem> Resolve(IEnumerable<OpeningItem> source,IEnumerable<OpeningLink> assignments,Func<string,int> wallUnits=null,Func<OpeningItem,bool> manualTotal=null){Func<string,int> units=w=>{if(wallUnits==null)return 1;int u=wallUnits(w);return u<1?1:u;};Func<OpeningLink,int> count=l=>l.Total?l.Quantity:checked(l.Quantity*units(l.Wall));var schedules=source.ToList();var links=assignments.ToList();var ids=schedules.ToDictionary(o=>o.Id,StringComparer.OrdinalIgnoreCase);var duplicates=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var l in links){OpeningItem item;if(string.IsNullOrWhiteSpace(l.Wall)||string.IsNullOrWhiteSpace(l.Schedule)||l.Quantity<1||l.Quantity>100000)throw new Exception("Check CHB schedule link and quantity.");if(!ids.TryGetValue(l.Schedule,out item)||item.Material=="Manual")throw new Exception("CHB schedule not found: "+l.Schedule);if(!duplicates.Add(l.Wall.Trim()+"\n"+l.Schedule.Trim()))throw new Exception("Duplicate opening schedule on wall "+l.Wall);}
  foreach(var g in links.GroupBy(l=>l.Schedule,StringComparer.OrdinalIgnoreCase))if(g.Sum(l=>(long)count(l))>ids[g.Key].Quantity)throw new Exception("CHB assignments exceed total schedule quantity for "+g.Key+" ("+g.Sum(l=>(long)count(l))+" needed: Qty per wall unit x Wall Qty). Increase schedule Qty or correct wall assignments.");var result=new List<OpeningItem>();foreach(var item in schedules){var use=links.Where(l=>string.Equals(l.Schedule,item.Id,StringComparison.OrdinalIgnoreCase)).ToList();if(item.Material=="Manual"){if(!string.IsNullOrWhiteSpace(item.Wall)){int u=manualTotal!=null&&manualTotal(item)?1:units(item.Wall);result.Add(u==1?item:new OpeningItem{Id=item.Id,Description=item.Description,Wall=item.Wall,Material=item.Material,Kind=item.Kind,Width=item.Width,Height=item.Height,Quantity=checked(item.Quantity*u)});}continue;}if(use.Count==0){if(!string.IsNullOrWhiteSpace(item.Wall))result.Add(item);continue;}foreach(var l in use)result.Add(new OpeningItem{Id=item.Id,Description=item.Description,Wall=l.Wall,Material=item.Material,Kind=item.Kind,Width=item.Width,Height=item.Height,Quantity=count(l)});}foreach(var wall in result.GroupBy(o=>o.Wall,StringComparer.OrdinalIgnoreCase))if(wall.Count()>3)throw new Exception("Maximum 3 opening entries per wall group: "+wall.Key);return result;}
 public static List<OpeningLink> Read(XmlElement root){var result=new List<OpeningLink>();var section=root["OpeningAssignments"];if(section==null)return result;foreach(XmlElement e in section.SelectNodes("Link")){int qty;if(!int.TryParse(e.GetAttribute("qty"),out qty)||qty<1||qty>100000||string.IsNullOrWhiteSpace(e.GetAttribute("wall"))||string.IsNullOrWhiteSpace(e.GetAttribute("schedule")))throw new Exception("Invalid saved CHB opening assignment.");result.Add(new OpeningLink{Wall=e.GetAttribute("wall"),Schedule=e.GetAttribute("schedule"),Quantity=qty,Total=!section.HasAttribute("perWallUnit")||e.GetAttribute("total")=="true"});}return result;}
 public static bool Legacy(XmlElement root){var section=root["OpeningAssignments"];return section==null||!section.HasAttribute("perWallUnit");}
 public static HashSet<string> ManualTotals(XmlElement root){var set=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var section=root["OpeningAssignments"];if(section!=null&&section.HasAttribute("manualTotals"))foreach(var id in section.GetAttribute("manualTotals").Split('|'))if(id.Trim()!="")set.Add(id.Trim());return set;}
 public static void Write(XmlElement root,IEnumerable<OpeningLink> links,IEnumerable<string> manualTotals=null){var section=root.OwnerDocument.CreateElement("OpeningAssignments");root.AppendChild(section);section.SetAttribute("perWallUnit","true");if(manualTotals!=null&&manualTotals.Any())section.SetAttribute("manualTotals",string.Join("|",manualTotals));foreach(var l in links){var e=root.OwnerDocument.CreateElement("Link");e.SetAttribute("wall",l.Wall);e.SetAttribute("schedule",l.Schedule);e.SetAttribute("qty",l.Quantity.ToString(System.Globalization.CultureInfo.InvariantCulture));if(l.Total)e.SetAttribute("total","true");section.AppendChild(e);}}
}
}
